// Rendering for this feature. State changes are handled by app.js and the domain models.
const questions=[
  {field:'activity',icon:'mountain',title:'What’s their weekend energy?',subtitle:'Think about the person you’d enjoy spending time with.',options:[['Active','Always up for an adventure','Trails, new places, a little spontaneity.'],['A bit of both','A little out, a little in','A plan on Saturday. A slow Sunday.'],['Easygoing','Cozy is a love language','A good meal, a film, nowhere to rush.'],['Any','I’m open to every pace','Let the connection surprise me.']]},
  {field:'workout',icon:'heart',title:'How much do they move?',subtitle:'Healthy habits can matter. Choose what feels right for you.',options:[['Works out often','Fitness is part of their routine','The gym, a run club, a regular class.'],['Works out sometimes or more','They move now and then','A walk, a hike, a class when they can.'],['Any','Fitness isn’t a deal-breaker','I’m here for the person.']]},
  {field:'energy',icon:'people',title:'What kind of social spark?',subtitle:'Quiet chemistry, a big personality, or somewhere between?',options:[['Introvert','Thoughtful & more introverted','Deep conversations over big crowds.'],['Somewhere in between','Somewhere in between','Happy socializing, happy recharging.'],['Extrovert','Outgoing & more extroverted','They bring a little life to the room.'],['Any','Different energies can click','I’m open to all of these.']]},
  {field:'pets',icon:'heart',title:'Room for a four-legged plus-one?',subtitle:'A small question that can make a big difference.',options:[['Love animals','An animal person, please','They love having pets in the picture.'],['Prefer pet-free','A pet-free kind of life','I’d prefer someone who feels the same.'],['Any','I’m flexible about pets','It’s the person I’m here to meet.']]},
  {field:'interests',icon:'coffee',title:'What would you love to share?',subtitle:'Pick a few interests, or keep this part open.',multi:interestOptions},
  {field:'values',icon:'flower',title:'What matters under the surface?',subtitle:'Choose the qualities you’d like to find. These help rank common ground.',multi:valueOptions},
  {field:'alignment',icon:'spark',title:'A few lifestyle must-haves.',subtitle:'Drinking, smoking and politics. Your own answers stay in Profile.'},
  {field:'family',icon:'people',title:'Kids, someday?',subtitle:'Better to know before the first coffee.',options:[['Wants children','They want children','Now or someday, kids are in the picture.'],['Doesn’t want children','They don’t want children','A child-free future.'],['Any','Open either way','We can talk about it.']]},
  {field:'background',icon:'flower',title:'Faith & background.',subtitle:'Optional. Choose everyone you’re open to, or keep it open. These choices stay private.'},
  {field:'boundaries',icon:'pin',title:'Who are you open to meeting?',subtitle:'Age, height, distance and intentions. No photos, ever.'},
];
const questionIndex=field=>questions.findIndex(q=>q.field===field);
function showQuestionNav(){return state.view==='home'&&state.profile.complete&&!state.booking&&!state.session&&state.deck.step!=='review';}
function questionNav(){return`<div class="question-navigation"><button class="pass-button" data-action="question-back" aria-label="Previous question" ${state.deck.step===0?'disabled':''}>${icon('back')}</button>${button(state.deck.step===deckLast?'Review my type':'Next question','question-next')}</div>`;}
function homePage(){
  if(!state.profile.complete)return welcomePage();
  if(state.session)return sessionPage();
  if(state.booking)return`${pageHeading('Let the butterflies begin','Your first hello<br><em>is on the calendar.</em>','You can review the plan or request a change from Dates.')}<section class="booked-connection"><img src="assets/${venueById(state.booking.venueId).photo}" alt="Illustrative dining space"><div><h2>${esc(venueById(state.booking.venueId).name)}</h2><p>${dateLabel(state.booking.timestamp)} · ${timeLabel(state.booking.timestamp)}</p>${button('View my date','navigate','primary','data-view="dates"','heart')}</div></section><p class="page-note">One active date at a time in this prototype.</p>`;
  return state.deck.step==='review'?preferenceReview():questionPage();
}
function welcomePage(){return`${pageHeading('Blind dates. Better stories.','First, a little<br><em>about you.</em>','Tell us who you are before you describe who you’d love to meet.')}<article class="discovery-card"><div class="discovery-photo"><img src="assets/first-hello.webp" alt="Date-night inspiration, with faces out of frame"><span class="photo-label">${icon('lock')} Your face stays a mystery</span><div class="photo-title"><h2>A little personality.<br>A little possibility.</h2></div></div><div class="discovery-body"><p class="welcome-copy">Age and education. Your energy, interests and values. How you’d feel comfortable sharing the bill.</p>${button(state.drafts.profile?'Continue my profile':'Create my profile','onboarding','primary','','heart')}<span class="intro-price">Then explore your type with a few swipe-style questions.</span></div></article>${state.booking?button('View my saved date','navigate','secondary','data-view="dates"','calendar'):''}<button class="safety-link" data-action="safety">${icon('shield')} Your pace. Your choice. Always.</button>`;}
function questionPage(){
  const q=questions[state.deck.step],p=state.deck.answers;
  let content='';
  if(q.options)content=`<div class="answer-list" role="group" aria-label="${esc(q.title)}">${q.options.map(([value,title,detail])=>`<button class="answer-option ${p[q.field]===value?'selected':''}" data-action="preference-choice" data-group="${q.field}" data-value="${value}" aria-pressed="${p[q.field]===value}"><span><strong>${title}</strong><span>${detail}</span></span><span class="answer-check">${p[q.field]===value?icon('check'):''}</span></button>`).join('')}</div>`;
  if(q.multi)content=`<div class="choice-group preference-chips" role="group" aria-label="${q.field}">${q.multi.map(value=>`<button class="choice ${p[q.field].includes(value)?'selected':''}" data-action="preference-choice" data-group="${q.field}" data-value="${esc(value)}" data-multi="true" aria-pressed="${p[q.field].includes(value)}">${esc(value)}${p[q.field].includes(value)?icon('check'):''}</button>`).join('')}</div><button class="open-answer ${!p[q.field].length?'selected':''}" data-action="preference-open" data-group="${q.field}" aria-pressed="${!p[q.field].length}">${icon('spark')} Keep this part open</button><p class="caption">These help prioritize introductions. They aren’t appearance filters.</p>`;
  if(q.field==='alignment')content=`${prefSelect('Political compatibility','politics',[['Any','Open to different views'],['Similar views','Similar views matter to me']])}${preferenceError('politics')}${prefSelect('Smoking preference','smoking',[['Any','I’m flexible'],['Non-smoker only','Non-smoker only']])}${prefSelect('Drinking preference','drinking',[['Any','I’m flexible'],['No heavy drinking','No heavy drinking'],['Non-drinker only','Non-drinker only']])}<p class="caption">If similar political views matter, add your own view in Profile so it can be compared.</p>`;
  if(q.field==='background')content=`${openToGroup('Faith I’m open to','religions',Dating.religions.filter(r=>r!=='Prefer not to say'))}${openToGroup('Backgrounds I’m open to','ethnicities',Dating.ethnicities.filter(r=>r!=='Prefer not to say'))}<p class="caption">If you choose any, people who prefer not to share theirs won’t be introduced to you. Nobody sees what you picked here.</p>`;
  if(q.field==='boundaries')content=`<div class="sentence-builder"><span>I’d like to meet</span>${pillSelect('I’d like to meet','meet',[['Everyone','Everyone'],['Man','Men'],['Woman','Women'],['Non-binary','Non-binary people']])}<span>ages</span>${pillNumber('Age from','minAge')}<span>to</span>${pillNumber('Age to','maxAge')}${pillSelect('Height','height',[['Any','any height'],['Taller than me','taller than me'],['Shorter than me','shorter than me']])}<span>who are within</span><span class="pill-field pill-static"><span id="radius-value">${esc(p.radius)}</span>&nbsp;km</span></div>${preferenceError('minAge')}${preferenceError('maxAge')}${preferenceError('height')}<div class="field"><label for="pref-radius">Travel radius</label><input class="range-input" id="pref-radius" type="range" min="5" max="50" step="5" value="${p.radius}" data-pref-field="radius"><div class="range-labels"><span>5 km</span><span>50 km</span></div>${preferenceError('radius')}</div>${prefSelect('Their relationship intentions','intent',[['Any','Open to compatible intentions'],...Dating.intents.map(v=>[v,v])])}${stretchToggle()}`;
  return`<div class="deck-heading">${pageHeading('','Your kind of <em>chemistry.</em>')}</div><div class="deck-meta"><span>Question ${state.deck.step+1} of ${questions.length}</span>${state.savedPreferences?'<button class="text-pill" data-action="use-saved">Use saved type '+icon('arrow')+'</button>':''}</div><div class="card-stack ${state.deck.step>=questions.length-1?'last-card':''}"><article class="question-card" data-swipe-card><div class="story-bars" role="progressbar" aria-label="Question ${state.deck.step+1} of ${questions.length}" aria-valuemin="1" aria-valuemax="${questions.length}" aria-valuenow="${state.deck.step+1}">${questions.map((_,i)=>`<span class="${i<=state.deck.step?'filled':''}"></span>`).join('')}</div><div class="question-grip" tabindex="0" aria-label="Swipe or use left and right arrow keys to move between questions"><span>${icon(q.icon)} About them</span><span>${icon('back')}${icon('chevron')}</span></div><h2 class="question-title" tabindex="-1">${q.title}</h2><p class="question-description">${q.subtitle}</p>${content}</article></div><p class="deck-hint">${questions[state.deck.step]?.options?'Tap an answer to continue. Swipe back to change it.':'Choose any that fit, then swipe or tap Next.'}</p><p class="draft-note" data-preference-saved>Answers are drafted here. You choose whether to reuse them at the end.</p>`;
}
function stretchToggle(){const on=!!(state.deck.answers.stretch&&isMember());return`<button class="open-answer stretch-toggle ${on?'selected':''}" data-action="toggle-stretch" aria-pressed="${on}">${icon(isMember()?'spark':'lock')}<span>Show me people slightly outside my age and distance if there’s no one<small>${isMember()?'Up to 3 years and 10 km. Deal-breakers never stretch.':'blinddate+ feature'}</small></span></button>`;}
function preferenceError(key){return preferenceErrors[key]?`<p class="field-error" role="alert">${esc(preferenceErrors[key])}</p>`:'';}
function prefInput(label,key,type,extra=''){return`<div class="field"><label for="pref-${key}">${label}</label><input class="input" id="pref-${key}" data-pref-field="${key}" type="${type}" value="${esc(state.deck.answers[key])}" ${extra}>${preferenceError(key)}</div>`;}
// Tinder-style sentence pills. Same ids and data-pref-field hooks as the plain fields.
function openToGroup(label,key,options){const list=state.deck.answers[key];return`<div class="field"><span class="field-label">${label}</span><button class="open-answer ${!list.length?'selected':''}" data-action="preference-open" data-group="${key}" aria-pressed="${!list.length}">${icon('spark')} Open to everyone</button><div class="choice-group" role="group" aria-label="${label}">${options.map(value=>`<button class="choice ${list.includes(value)?'selected':''}" data-action="preference-choice" data-group="${key}" data-value="${esc(value)}" data-multi="true" aria-pressed="${list.includes(value)}">${esc(value)}${list.includes(value)?icon('check'):''}</button>`).join('')}</div></div>`;}
function pillSelect(label,key,options){return`<label class="pill-field pill-select"><span class="sr-only">${label}</span><select id="pref-${key}" data-pref-field="${key}">${options.map(([value,title])=>`<option value="${esc(value)}" ${state.deck.answers[key]===value?'selected':''}>${esc(title)}</option>`).join('')}</select>${icon('down')}</label>`;}
function pillNumber(label,key){return`<label class="pill-field pill-number"><span class="sr-only">${label}</span><input id="pref-${key}" data-pref-field="${key}" type="number" min="18" max="100" inputmode="numeric" value="${esc(state.deck.answers[key])}" ${preferenceErrors[key]?'aria-invalid="true"':''}></label>`;}
function prefSelect(label,key,options){return`<div class="field"><label for="pref-${key}">${label}</label><select class="input" id="pref-${key}" data-pref-field="${key}">${options.map(([value,title])=>`<option value="${esc(value)}" ${state.deck.answers[key]===value?'selected':''}>${esc(title)}</option>`).join('')}</select></div>`;}
function preferenceSummary(p){return`<div class="type-summary"><div><span>Their energy</span><strong>${p.energy==='Any'?'Open to every energy':esc(p.energy)}</strong></div><div><span>Their pace</span><strong>${p.activity==='Any'?'Open to every pace':esc(p.activity)}</strong></div><div><span>Pets</span><strong>${p.pets==='Any'?'Flexible':esc(p.pets)}</strong></div><div><span>Connection</span><strong>${esc(p.meet)} · ${p.minAge}–${p.maxAge} · ${p.radius} km</strong></div><div><span>Intentions</span><strong>${p.intent==='Any'?'Compatible intentions':esc(p.intent)}</strong></div><div><span>Shared interests</span><strong>${p.interests.length?p.interests.map(esc).join(' · '):'Open to discovering new things'}</strong></div><div><span>Values</span><strong>${p.values.length?p.values.map(esc).join(' · '):'Open to seeing what clicks'}</strong></div><div><span>Lifestyle</span><strong>${p.politics==='Similar views'?'Similar political views':'Open to different views'} · ${p.smoking==='Any'?'Flexible about smoking':'Non-smoker only'} · ${p.drinking==='Any'?'Flexible about drinking':esc(p.drinking)}</strong></div><div><span>Fitness</span><strong>${p.workout==='Any'?'Not a deal-breaker':esc(p.workout)}</strong></div><div><span>Family plans</span><strong>${p.family==='Any'?'Open either way':esc(p.family)}</strong></div><div><span>Height</span><strong>${p.height==='Any'?'Any height':esc(p.height)}</strong></div><div><span>Faith</span><strong>${p.religions.length?p.religions.map(esc).join(' · '):'Open to everyone'}</strong></div><div><span>Background</span><strong>${p.ethnicities.length?p.ethnicities.map(esc).join(' · '):'Open to everyone'}</strong></div></div>`;}
// A playful one-line read-back of the person's own answers (inspired by Tinder's "vibe" card). Not a score.
function vibeLine(p){
  const pace={Active:'trail mornings','A bit of both':'busy Saturdays',Easygoing:'cozy dinners'}[p.activity];
  const shared={Outdoors:'long walks',Animals:'saying hi to every dog','Slow Sundays':'slow Sundays',Cooking:'cooking together',Travel:'little trips',Fitness:'a morning workout','Arts & culture':'gallery afternoons','Live music':'live music',Coffee:'tiny coffee shops'}[p.interests[0]]||({Introvert:'deep conversations',Extrovert:'a lively room','Somewhere in between':'good company'}[p.energy]||'good conversation');
  const end=p.intent==='A long-term relationship'?', with something real in mind':p.intent==='Open to exploring'?' while you’re both figuring it out':'';
  return pace?`Your type screams <em>${esc(pace)}</em> and <em>${esc(shared)}</em>${esc(end)}.`:`Your type keeps it open: <em>${esc(shared)}</em> first${esc(end)}.`;
}
function sentencePill(text,step){return`<button class="pill-field pill-link" data-action="edit-question" data-value="${step}" aria-label="Change: ${esc(text)}">${esc(text)}${icon('chevron')}</button>`;}
function preferenceReview(){const p=state.deck.answers,who={Everyone:'everyone',Man:'men',Woman:'women','Non-binary':'non-binary people'}[p.meet]||esc(p.meet);return`${pageHeading('A type, not a checklist','Keep this feeling.<br><em>Or keep exploring.</em>','Save these answers for future blind dates, or use them only for this introduction.')}<section class="vibe-card"><p class="vibe-line">${vibeLine(p)}</p><span class="vibe-caption">${icon('spark')} A read-back of your answers, not a score</span></section><div class="sentence-builder sentence-summary"><span>Looking for</span>${sentencePill(who,deckLast)}<span>ages</span>${sentencePill(`${p.minAge}–${p.maxAge}`,deckLast)}${p.height!=='Any'?sentencePill(p.height.toLowerCase(),deckLast):''}<span>who are within</span>${sentencePill(`${p.radius} km`,deckLast)}</div><section class="panel">${preferenceSummary(p)}</section><div class="save-type-options">${button('Save my type & continue','save-type','primary','','heart')}<p>These become your saved preferences for future introductions.</p>${button('Explore just this time','explore-once','secondary','','spark')}<p>This search uses these answers. Your saved type won’t change.</p></div><button class="why-link" data-action="edit-questions">${icon('back')} Back to the questions</button>`;}
